cat > /tmp/scan_nd.mjs <<'EOF'
const ND = /\p{Nd}/u;
const runs = [];
let cur = null;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  // skip surrogates - fromCodePoint works but they're not Nd anyway
  const isNd = ND.test(String.fromCodePoint(cp));
  if (isNd) {
    if (cur === null) cur = { start: cp, end: cp };
    else cur.end = cp;
  } else {
    if (cur !== null) { runs.push(cur); cur = null; }
  }
}
if (cur !== null) runs.push(cur);

const hex = n => 'U+' + n.toString(16).toUpperCase().padStart(4, '0');
console.log('total Nd runs:', runs.length);
console.log('total Nd code points:', runs.reduce((a, r) => a + (r.end - r.start + 1), 0));

const notMult10 = runs.filter(r => ((r.end - r.start + 1) % 10) !== 0);
console.log('\n=== runs whose length is NOT a multiple of 10:', notMult10.length, '===');
for (const r of notMult10) console.log(hex(r.start), '..', hex(r.end), 'len', r.end - r.start + 1);

const longer10 = runs.filter(r => (r.end - r.start + 1) > 10);
console.log('\n=== runs LONGER than 10:', longer10.length, '===');
for (const r of longer10) console.log(hex(r.start), '..', hex(r.end), 'len', r.end - r.start + 1);

console.log('\n=== all runs ===');
for (const r of runs) console.log(hex(r.start), '..', hex(r.end), 'len', r.end - r.start + 1);
EOF
node /tmp/scan_nd.mjs

cat > /tmp/gen_nd.mjs <<'EOF'
import { writeFileSync } from 'fs';
const ND = /\p{Nd}/u;
const runs = [];
let cur = null;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (ND.test(String.fromCodePoint(cp))) {
    if (cur === null) cur = { start: cp, end: cp }; else cur.end = cp;
  } else if (cur !== null) { runs.push(cur); cur = null; }
}
if (cur) runs.push(cur);

// split every run into aligned 10-code-point blocks
const blocks = [];
for (const r of runs) {
  for (let s = r.start; s <= r.end; s += 10) {
    blocks.push({ start: s, runStart: r.start, runLen: r.end - r.start + 1 });
  }
}
const hex = n => n.toString(16).toUpperCase().padStart(4, '0');
const d = (b, v) => String.fromCodePoint(b.start + v);

const cases = [];
for (const b of blocks) {
  const tag = 'U+' + hex(b.start);
  // singly, 0..9
  for (let v = 0; v <= 9; v++) {
    cases.push({ name: `${tag}-single-${v}`, argv: ['--a', 'x', '--b', d(b, v)] });
  }
  // multi-digit
  let asc = ''; for (let v = 0; v <= 9; v++) asc += d(b, v);
  let desc = ''; for (let v = 9; v >= 0; v--) desc += d(b, v);
  cases.push({ name: `${tag}-asc10`, argv: ['--a', 'x', '--b', asc] });          // 123456789
  cases.push({ name: `${tag}-desc10`, argv: ['--a', 'x', '--b', desc] });        // 9876543210
  cases.push({ name: `${tag}-42`, argv: ['--a', 'x', '--b', d(b,4)+d(b,2)] });
  cases.push({ name: `${tag}-lead0-007`, argv: ['--a', 'x', '--b', d(b,0)+d(b,0)+d(b,7)] });
  cases.push({ name: `${tag}-1e6`, argv: ['--a','x','--b', d(b,1)+d(b,0).repeat(6)] });
  cases.push({ name: `${tag}-neg-13`, argv: ['--a','x','--b', '-'+d(b,1)+d(b,3)] });
  cases.push({ name: `${tag}-plus-58`, argv: ['--a','x','--b', '+'+d(b,5)+d(b,8)] });
  cases.push({ name: `${tag}-us-1_5`, argv: ['--a','x','--b', d(b,1)+'_'+d(b,5)] });
}
writeFileSync('/tmp/nd-blocks-all.json', JSON.stringify(cases));
console.log('blocks:', blocks.length, 'cases:', cases.length);
console.log('blocks in the 50-run:', blocks.filter(b=>b.runLen===50).map(b=>'U+'+hex(b.start)).join(' '));
EOF
